// BenchmarkRunDetail defines model for BenchmarkRunDetail.
type BenchmarkRunDetail struct {
	BaselineRunId           *int                                `json:"baseline_run_id,omitempty"`
	Configuration           interface{}                         `json:"configuration,omitempty"`
	ConfigurationHash       string                              `json:"configuration_hash"`
	Coverage                *BenchmarkCoverage                  `json:"coverage,omitempty"`
	CreatedAt               *time.Time                          `json:"created_at,omitempty"`
	DatasetId               int                                 `json:"dataset_id"`
	DatasetVersion          int                                 `json:"dataset_version"`
	DirectionalOnly         *bool                               `json:"directional_only,omitempty"`
	Error                   *string                             `json:"error,omitempty"`
	FinishedAt              *time.Time                          `json:"finished_at,omitempty"`
	Id                      *int                                `json:"id,omitempty"`
	IsBaseline              *bool                               `json:"is_baseline,omitempty"`
	Label                   *string                             `json:"label,omitempty"`
	Metrics                 interface{}                         `json:"metrics,omitempty"`
	Model                   *string                             `json:"model,omitempty"`
	ModelsDisplay           *string                             `json:"models_display,omitempty"`
	OrganizationSlug        *string                             `json:"organization_slug,omitempty"`
	PassAtK                 *float64                            `json:"pass_at_k,omitempty"`
	PassPowK                *float64                            `json:"pass_pow_k,omitempty"`
	PentestCategoryCoverage *PentestCategoryCoverage            `json:"pentest_category_coverage,omitempty"`
	ReasoningEffort         *BenchmarkRunDetail_ReasoningEffort `json:"reasoning_effort,omitempty"`
	Repeats                 *int                                `json:"repeats,omitempty"`

	// ScorerVersion Which rubric produced these numbers. Surfaced because re-scoring adds versions
	// rather than replacing them, and a rate read against the wrong one is meaningless.
	//
	// The generic summary resolves this from the default `accuracy` scorer, which a pentest run has
	// no scores under — so for pentest it reads the active version off the stored aggregate instead
	// of reporting `null` ("not scored yet") on a run that is in fact recall-scored.
	ScorerVersion *string    `json:"scorer_version,omitempty"`
	SpendCapUsd   *string    `json:"spend_cap_usd,omitempty"`
	StartedAt     *time.Time `json:"started_at,omitempty"`

	// Status * `pending` - Pending
	// * `dispatching` - Dispatching
	// * `running` - Running
	// * `scoring` - Scoring
	// * `completed` - Completed
	// * `partial` - Partial
	// * `failed` - Failed
	Status      *BenchmarkRunStatusEnum `json:"status,omitempty"`
	StatusLabel string                  `json:"status_label"`
	SuiteKey    string                  `json:"suite_key"`
	SuiteLabel  *string                 `json:"suite_label,omitempty"`
	TargetKey   *string                 `json:"target_key,omitempty"`

	// Tier * `smoke` - Smoke
	// * `full` - Full
	Tier             *TierEnum `json:"tier,omitempty"`
	TierLabel        string    `json:"tier_label"`
	TriggeredByEmail *string   `json:"triggered_by_email,omitempty"`

	// Validity Measurement validity flags and codes.
	Validity *map[string]interface{} `json:"validity,omitempty"`
}

